		throw new FeatureFlagsError("configuration");
	async function guard(
		tx: FlagTransaction,
		actor: FlagActor,
		operation: "create" | "update" | "override" | "list",
	) {
		if (!actor?.userId) throw new FeatureFlagsError("unauthenticated");
		opaqueId(actor.userId);
