			await setFlagTransactionBounds(tx);
			await guard(tx, actor, "create");
			const now = new Date();
			const [created] = await tx
				.insert(definitions)
				.values({ key, ...values, revision: 1, createdAt: now, updatedAt: now })
				.returning();
			await options.audit?.(tx, {
				action: "flags.create",
				flagId: key,
				revision: 1,
			});
