				...row,
				...Object.fromEntries(
					Object.entries(input).filter(([k]) =>
						[
							"description",
							"enabled",
							"defaultValue",
							"rolloutBasisPoints",
						].includes(k),
					),
				),
			});
			if (Object.entries(values).every(([k, v]) => Reflect.get(row, k) === v))
				return row;
