				.update(definitions)
				.set({ ...values, revision: revision + 1, updatedAt: new Date() })
				.where(eq(definitions.key, key))
				.returning();
			await options.audit?.(tx, {
				action: "flags.update",
				flagId: key,
				revision: updated.revision,
			});
